from solution import check_k_elements


def test_issue_example_all_fours():
    """Check if the given tuple list has all k elements."""
    assert check_k_elements([(4, 4), (4, 4, 4), (4, 4), (4, 4, 4, 4), (4,)], 4) == True  # 5-5=0 mismatches -> True


def test_issue_single_tuple_all_k():
    """Check if the given tuple list has all k elements."""
    assert check_k_elements([(7, 7, 7)], 7) == True  # 3-3=0 mismatches -> True


def test_issue_single_tuple_not_k():
    """Check if the given tuple list has all k elements."""
    assert check_k_elements([(7, 7, 8)], 7) == False  # 8-7=1 difference -> False


