    assert check_k_elements([(1, 1), (1, 2)], 1) == False  # 2-1=1 difference -> False


def test_issue_value_just_below_k():
    """Check if the given tuple list has all k elements."""
    assert check_k_elements([(4, 4), (4, 3)], 4) == False  # 4-1=3 mismatch -> False


def test_issue_value_just_above_k():
    """Check if the given tuple list has all k elements."""
    assert check_k_elements([(4, 4), (4, 5)], 4) == False  # 4+1=5 mismatch -> False


def test_issue_other_k_value_all_match():
