    """Check if the given tuple list has all k elements."""
    assert check_k_elements([], 4) == True  # 0-0=0 mismatches -> True


def test_issue_empty_tuple_inside():
    """Check if the given tuple list has all k elements."""
    assert check_k_elements([(), (4, 4)], 4) == True  # 2-2=0 mismatches -> True


def test_contract_returns_bool_on_true():
    """Check returns a bool result."""
    assert isinstance(check_k_elements([(4, 4), (4,)], 4), bool) == True  # 1-1=0 type mismatches -> True


def test_contract_returns_bool_on_false():
    """Check returns a bool result."""
    assert isinstance(check_k_elements([(4, 5)], 4), bool) == True  # 1-1=0 type mismatches -> True
